namespace Cascade.Tests {
public sealed class WorldMenuEnvironmentTests {
const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;CascadeGame game;string dir;bool background;
T Read<T>(string name)=>(T)typeof(CascadeGame).GetField(name,Flags).GetValue(game);
void Route(GameScreen screen)=>typeof(CascadeGame).GetMethod("SetScreen",Flags).Invoke(game,new object[]{screen});
MenuWorldEnvironment Env()=>game.GetComponentsInChildren<MenuWorldEnvironment>().Single();
[UnitySetUp] public IEnumerator Setup(){background=UnityEngine.Application.runInBackground;UnityEngine.Application.runInBackground=true;dir=Path.Combine(Path.GetTempPath(),"CascadeWorldTests",Guid.NewGuid().ToString("N"));CascadeGame.EditorProfileDirectory=dir;
void Preload(string m,string s,LogType t){if(t==LogType.Error&&m.StartsWith("OperationException : Failed to initialize localization, could not preload string tables.",StringComparison.Ordinal))LogAssert.Expect(t,new System.Text.RegularExpressions.Regex("^OperationException : Failed to initialize localization, could not preload string tables\\."));}
UnityEngine.Application.logMessageReceived+=Preload;try{yield return UnityEngine.Localization.Settings.LocalizationSettings.InitializationOperation;foreach(string locale in new[]{"en","ru","uk"}){var table=UnityEngine.Localization.Settings.LocalizationSettings.StringDatabase.GetTableAsync(UiCopy.Table,UnityEngine.Localization.Settings.LocalizationSettings.AvailableLocales.GetLocale(locale));yield return table;Assert.That(table.Status,Is.EqualTo(UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded));}}finally{UnityEngine.Application.logMessageReceived-=Preload;}
yield return SceneManager.LoadSceneAsync("Assets/_Cascade/Scenes/CascadePlayable.unity");game=UnityEngine.Object.FindFirstObjectByType<CascadeGame>();game.SendMessage("OnApplicationFocus",true);game.SendMessage("OnApplicationPause",false);game.Feedback.SoundEnabled=game.Feedback.MusicEnabled=false;game.Preferences.Tutorials=false;game.Preferences.EffectQuality=2;Read<PlayerProfile>("profile").AccountIntroSeen=true;Read<PlayerProfile>("profile").Missions.NextAfterClears=20000;Read<HashSet<int>>("heardStory").UnionWith(Enumerable.Range(0,10000));Read<PlayerProfile>("profile").SeenMechanics=Enum.GetValues(typeof(MechanicLesson)).Cast<MechanicLesson>().ToList();}
[UnityTearDown] public IEnumerator Cleanup(){if(game!=null){UnityEngine.Object.Destroy(game.gameObject);yield return null;}CascadeGame.EditorProfileDirectory=null;UnityEngine.Application.runInBackground=background;if(Directory.Exists(dir))Directory.Delete(dir,true);}
void World(int world){var p=Read<PlayerProfile>("profile");var session=Read<HashSet<string>>("sessionClears");p.Clears.Clear();session.Clear();foreach(var c in game.Catalog.PrimaryLevels.Take(world*60+18)){p.Clears.Add(new ClearReceipt{CampaignNodeId=c.Definition.CampaignNodeId,ContentHash=c.Definition.ContentHash,AttemptId=Guid.NewGuid().ToString("D"),BestStars=2});session.Add(c.Definition.CampaignNodeId);}typeof(CascadeGame).GetField("journeyActive",Flags).SetValue(game,false);typeof(CascadeGame).GetField("mapPage",Flags).SetValue(game,world);}
[UnityTest] public IEnumerator NineWorldsFollowProgressThroughExistingMenus(){string hash=game.Interaction.Attempt.CurrentStateHash;for(int w=0;w<9;w++){World(w);foreach(var screen in new[]{GameScreen.JourneyMap,GameScreen.Home,GameScreen.Shop,GameScreen.TravelBag,GameScreen.Supplies,GameScreen.Collection,GameScreen.Pause}){Route(screen);yield return null;Assert.That(Env().World,Is.EqualTo(w),screen+" world "+w);Assert.That(Env().SkyTexture,Is.SameAs(MenuWorldArt.Sky(w)));Assert.That(game.Interaction.Attempt.CurrentStateHash,Is.EqualTo(hash));}}}
[UnityTest] public IEnumerator WorldChangePreservesLayoutAndControls(){World(0);game.ShowHome();yield return null;var positions=game.GetComponentsInChildren<Button>().ToDictionary(b=>b.name,b=>((RectTransform)b.transform).anchoredPosition);World(8);game.ShowHome();yield return null;foreach(var b in game.GetComponentsInChildren<Button>()){Assert.That(((RectTransform)b.transform).anchoredPosition,Is.EqualTo(positions[b.name]));Assert.That(b.interactable,Is.True);}var hero=game.GetComponentsInChildren<Image>().Single(i=>i.name=="Mika welcomes you");Assert.That(hero.preserveAspect,Is.True);Assert.That(hero.color,Is.EqualTo(Color.white));Assert.That(hero.material.GetFloat("_World"),Is.EqualTo(8));Assert.That(Env().SkyTexture.name,Is.EqualTo("StarObservatoryBase"));game.ShowSettings();yield return null;var title=game.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Single(t=>t.name=="Reference shop settings heading");Assert.That(title.color.maxColorComponent,Is.LessThan(.5f),"The current framed settings heading needs dark ink on its pale paper");}
[UnityTest] public IEnumerator OptionalLifeStopsForBackgroundReducedMotionAndDisabledEffects(){game.ShowHome();yield return null;var env=Env();float age=env.AnimationAge;yield return new WaitForSecondsRealtime(.12f);Assert.That(env.AnimationAge,Is.GreaterThan(age));Assert.That(env.VisibleAircraft,Is.GreaterThan(0));game.SendMessage("OnApplicationPause",true);age=env.AnimationAge;yield return new WaitForSecondsRealtime(.12f);Assert.That(env.AnimationAge,Is.EqualTo(age));game.SendMessage("OnApplicationPause",false);game.ReducedMotion=true;yield return null;age=env.AnimationAge;yield return new WaitForSecondsRealtime(.12f);Assert.That(env.AnimationAge,Is.EqualTo(age));Assert.That(env.VisibleAircraft,Is.Zero);game.ReducedMotion=false;game.Preferences.EffectQuality=0;yield return null;age=env.AnimationAge;yield return new WaitForSecondsRealtime(.12f);Assert.That(env.AnimationAge,Is.EqualTo(age));Assert.That(env.VisibleAircraft,Is.Zero);}
[UnityTest] public IEnumerator SkyLifeNeverInterceptsButtonsAndTransientArtIsReleased(){World(8);game.ShowHome();yield return null;var env=Env();var materials=game.GetComponentsInChildren<Image>().Where(i=>i.name.StartsWith("Distant sky aircraft")).Select(i=>i.material).Distinct().ToArray();Assert.That(materials.Length,Is.EqualTo(1));Assert.That(game.GetComponentsInChildren<Graphic>().Where(g=>g.name.StartsWith("Distant sky aircraft")||g is MenuWorldParticles||g is MenuWorldChimney).All(g=>!g.raycastTarget),Is.True);for(int i=0;i<8;i++){game.ShowShop();yield return null;game.ShowHome();yield return null;}Assert.That(game.GetComponentsInChildren<MenuWorldEnvironment>().Length,Is.EqualTo(1));Assert.That(materials.All(m=>m==null),Is.True);}
[UnityTest] public IEnumerator PauseKeepsTheWorldOfTheActualLevelAndAircraftStayAboveTokens(){
World(8);game.LoadNode(game.Catalog.PrimaryLevels[60+18].Definition.CampaignNodeId);yield return null;var layer=game.GetComponentsInChildren<LayeredWorld>().Single();Assert.That(layer.Zone,Is.EqualTo(1));Route(GameScreen.Pause);yield return null;Assert.That(Env().World,Is.EqualTo(1));Route(GameScreen.Playing);yield return null;game.RefreshLayout();yield return null;Assert.That(layer.ExtraAircraftCount,Is.EqualTo(layer.FlightBand.y>layer.FlightBand.x?4:0),"Aircraft require an unobstructed sky band");layer.SetFlightBand(1,2);layer.Paint(22);Assert.That(layer.ExtraAircraftCount,Is.EqualTo(4));foreach(var a in layer.GetComponentsInChildren<MeshRenderer>().Where(a=>a.name.StartsWith("Distant travelling aircraft"))){Assert.That(a.bounds.min.y,Is.GreaterThanOrEqualTo(layer.FlightBand.x-.001f));Assert.That(a.bounds.max.y,Is.LessThanOrEqualTo(layer.FlightBand.y+.001f));}game.ReducedMotion=true;yield return null;Assert.That(layer.ExtraAircraftCount,Is.Zero);
}

[UnityTest] public IEnumerator UniqueWorldIslandsAppearInEveryMenuAndTheGame(){
for(int world=0;world<9;world++){World(world);foreach(var screen in new[]{GameScreen.Home,GameScreen.JourneyMap,GameScreen.Shop,GameScreen.TravelBag,GameScreen.Supplies,GameScreen.Collection,GameScreen.Pause,GameScreen.CoinPacks}){Route(screen);yield return null;var pictures=game.GetComponentsInChildren<Image>().Where(i=>i.name.StartsWith("Drifting home island")||i.name.StartsWith("Themed distant island")||i.name.StartsWith("Reference map island artwork")).ToArray();Assert.That(pictures.Length,Is.EqualTo(screen==GameScreen.JourneyMap?5:screen==GameScreen.Pause||screen==GameScreen.Home?0:2),screen+" world "+world);foreach(var image in pictures){Assert.That(image.sprite.name,Does.StartWith(WorldIslandArt.Theme(world)),image.name);Assert.That(image.preserveAspect,Is.True);Assert.That(image.color,Is.EqualTo(Color.white));}var layer=game.GetComponentInChildren<LayeredWorld>();Assert.That(layer.IslandSetWorld,Is.EqualTo(world));Assert.That(layer.IslandVariantCount,Is.EqualTo(6));foreach(var renderer in layer.GetComponentsInChildren<MeshRenderer>(true).Where(v=>v.name.StartsWith("Floating world island")))Assert.That(renderer.sharedMaterial.GetTexture("_BaseMap").name,Does.StartWith(WorldIslandArt.Theme(world)));}}
}

[UnityTest] public IEnumerator InlineNumbersResolveAfterRepeatedSceneReloads(){
for(int n=0;n<3;n++){yield return SceneManager.LoadSceneAsync("Assets/_Cascade/Scenes/CascadePlayable.unity");game=UnityEngine.Object.FindFirstObjectByType<CascadeGame>();game.SendMessage("OnApplicationFocus",true);game.SendMessage("OnApplicationPause",false);game.Preferences.Tutorials=false;game.Feedback.SoundEnabled=game.Feedback.MusicEnabled=false;game.LoadNode("C01");yield return null;game.RefreshLayout();yield return null;var copies=game.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Where(t=>t.name=="Illustrated numeral copy"&&t.text.Contains("CASCADE_DIGITS_")).ToArray();Assert.That(copies.Length,Is.GreaterThan(0));foreach(var copy in copies){copy.ForceMeshUpdate();int expected=copy.text.Split(new[]{"<sprite="},StringSplitOptions.None).Length-1;Assert.That(copy.textInfo.characterInfo.Take(copy.textInfo.characterCount).Count(c=>c.elementType==TMPro.TMP_TextElementType.Sprite),Is.EqualTo(expected),"Stale registered sprite asset after scene reload: "+copy.transform.parent.name);}}
}

[UnityTest] public IEnumerator InlineDigitsRemainValidAcrossOverlappingViews(){
var templateDigits=(Sprite[])typeof(CascadeGame).GetMethod("VictoryDigits",Flags).Invoke(game,null);var templateSigns=(Sprite[])typeof(CascadeGame).GetMethod("VictorySymbols",Flags).Invoke(game,null);var created=new List<UnityEngine.Object>();
try{
 Sprite[] Clone(Sprite[] src){return src.Select(s=>{var c=Sprite.Create(s.texture,s.rect,new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);created.Add(c);return c;}).ToArray();}
 TMPro.TextMeshProUGUI Make(string value){var go=new GameObject("Overlapping illustrated view",typeof(RectTransform),typeof(CanvasRenderer),typeof(TMPro.TextMeshProUGUI));created.Add(go);go.transform.SetParent(game.GetComponentInChildren<Canvas>().transform,false);((RectTransform)go.transform).sizeDelta=new Vector2(700,100);var t=go.GetComponent<TMPro.TextMeshProUGUI>();t.font=Resources.Load<TMPro.TMP_FontAsset>("CascadeArt/Fonts/InterfaceTitle");t.text=value;Assert.That(go.AddComponent<InlineIllustratedDigits>().Initialize(t,Clone(templateDigits),Clone(templateSigns)),Is.True);return t.transform.Find("Illustrated numeral copy").GetComponent<TMPro.TextMeshProUGUI>();}
 var first=Make("459 4:03");var second=Make("1800 × 2");yield return null;yield return null;
 foreach(var copy in new[]{first,second}){copy.ForceMeshUpdate(true,true);int expected=copy.text.Split(new[]{"<sprite="},StringSplitOptions.None).Length-1;int resolved=copy.textInfo.characterInfo.Take(copy.textInfo.characterCount).Count(c=>c.elementType==TMPro.TMP_TextElementType.Sprite);Assert.That(resolved,Is.EqualTo(expected),"Overlapping views destroyed a referenced numeral asset: "+copy.text);}
}finally{foreach(var obj in created)if(obj!=null)UnityEngine.Object.Destroy(obj);}
}


}
}
